if(EditorApplication.isPlaying)throw new System.Exception("Edit only");var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();string D="ArtSource/Pipeline/Review/BriarwickEnvironment06";
var terrain=Terrain.activeTerrain;var td=terrain.terrainData;float Y(float x,float z){return terrain.SampleHeight(new Vector3(x,0,z))+terrain.transform.position.y;}float Creek(float x){return -68+6*Mathf.Sin(x/26)+.025f*x;}float S(float a,float b,float v){return Mathf.SmoothStep(0,1,Mathf.InverseLerp(a,b,v));}float Slope(Vector2 p){return td.GetSteepness((p.x-terrain.transform.position.x)/320,(p.y-terrain.transform.position.z)/320);}bool OldGrove(Vector2 p){return p.x> -63&&p.x<8&&p.y>43&&p.y<142;}
var layout=Newtonsoft.Json.Linq.JObject.Parse(System.IO.File.ReadAllText("ArtSource/Pipeline/Review/BriarwickHamletDev01/Layout.json"));var road=new System.Collections.Generic.List<Vector3>();foreach(var r in layout["routes"]){float half=(float)r["widthMetres"]*.5f;foreach(var q in r["points"])road.Add(new Vector3((float)q[0],(float)q[2],half));}float Road(Vector2 p){float best=999;foreach(var q in road){float dx=q.x-p.x,dz=q.y-p.y;float d=Mathf.Sqrt(dx*dx+dz*dz)-q.z;if(d<best)best=d;}return best;}
Bounds BoundsOf(GameObject go){var rr=go.GetComponentsInChildren<Renderer>().Where(r=>r.enabled&&r.gameObject.activeInHierarchy&&r.gameObject.layer!=2).ToArray();if(rr.Length==0)return new Bounds(Vector3.zero,Vector3.zero);var b=rr[0].bounds;foreach(var r in rr.Skip(1))b.Encapsulate(r.bounds);return b;}
var structures=new System.Collections.Generic.List<Bounds>();foreach(var g in scene.GetRootGameObjects().Where(g=>g.activeInHierarchy&&(g.name.Contains("architectural review")||g.name=="Stable A - rural thatch review03"))){var b=BoundsOf(g);if(b.size.sqrMagnitude>0)structures.Add(b);}foreach(Transform t in GameObject.Find("03 Eleven primary building locations").transform){var b=BoundsOf(t.gameObject);if(b.size.sqrMagnitude>0)structures.Add(b);}var plots=GameObject.Find("04 Common gardens farming and graveyard").GetComponentsInChildren<MeshRenderer>().Select(r=>r.bounds).ToArray();bool InBounds(Vector2 p,Bounds b,float extra){return p.x>=b.min.x-extra&&p.x<=b.max.x+extra&&p.y>=b.min.z-extra&&p.y<=b.max.z+extra;}bool Reserved(Vector2 p,float extra){return structures.Any(b=>InBounds(p,b,extra))||plots.Any(b=>InBounds(p,b,extra));}
bool Safe(Vector2 p,float radius){return p.x> -153&&p.x<153&&p.y> -163&&p.y<143&&!OldGrove(p)&&!Reserved(p,radius+1)&&Road(p)>radius+1.15f&&Mathf.Abs(p.y-Creek(p.x))>3.5f+radius&&Y(p.x,p.y)>4.15f&&Slope(p)<30;}
string Region(Vector2 p){if(Mathf.Abs(p.y-Creek(p.x))<13)return "CreekBanks";if(Mathf.Abs(p.x)<80&&p.y> -55&&p.y<48)return "VillageMargins";if(p.x> -82&&p.x<27&&p.y>35)return "WoodlandSkirts";if(Mathf.Abs(p.x)>126||p.y< -135||p.y>126)return "DistantCountryside";if(Mathf.Abs(p.x)>87||Slope(p)>8||p.y>100)return "Hillsides";return "Meadows";}


var j=Newtonsoft.Json.Linq.JObject.Parse(System.IO.File.ReadAllText(D+"/Integration.json"));var issues=new List<string>();float minRoad=999,minWater=999;int checkedPlants=0;foreach(var item in j["placements"]){var p=new Vector2(-160+((int)item["x"]+.5f)*320/512,-170+((int)item["z"]+.5f)*320/512);float rd=Road(p),water=Mathf.Abs(p.y-Creek(p.x));minRoad=Mathf.Min(minRoad,rd);minWater=Mathf.Min(minWater,water);if(Reserved(p,.9f)||rd<1.4f||water<4.2f||Slope(p)>30)issues.Add(item.ToString());checkedPlants++;}var report=new{checkedPlants,violations=issues,minRoadCentreCellDistanceFromRoadEdge=minRoad,minWaterCentreCellDistanceFromCreekAxis=minWater,method="Conservative source-cell masks, jitter+flower-radius allowance; not exhaustive triangle intersection testing",allBuildingsAddressed=j["buildingSurrounds"].All(s=>(int)s["paintedTexels"]>0&&(int)s["newFlowerClumps"]>0)};System.IO.File.WriteAllText(D+"/PlacementValidation.json",Newtonsoft.Json.JsonConvert.SerializeObject(report,Newtonsoft.Json.Formatting.Indented));return report;
